definition.script:
pipeline {
  agent any
  options { timestamps() }

  parameters {
    string(name: 'REPO_URL',      defaultValue: 'https://github.com/ljs14741/binary_star.git', description: '별말씀 프로젝트 Git URL')
    string(name: 'BRANCH',        defaultValue: 'master', description: '브랜치')
    string(name: 'CREDENTIALS',   defaultValue: 'github-hackathon', description: 'Git 크리덴셜 ID')
    string(name: 'DOCKERFILE',    defaultValue: 'Dockerfile', description: 'Dockerfile 경로')
    string(name: 'BUILD_CTX',     defaultValue: '.', description: 'docker build context')
    string(name: 'IMAGE_NAME',    defaultValue: 'star', description: '도커 이미지명')
    string(name: 'SERVICE_NAME',  defaultValue: 'star', description: 'compose 서비스 키')
    string(name: 'CONTAINER_NAME',defaultValue: 'star-app', description: '컨테이너 이름')
    string(name: 'COMPOSE_FILE',  defaultValue: '/home/binary/binaryworld/infra/docker-compose.yml', description: '서버 공용 compose 경로')
    string(name: 'NEXT_PUBLIC_KAKAO_JS_KEY', defaultValue: 'ea07c2afa5b5a0a07737bab48ab8e3e8', description: '카카오 JS 키 (빌드 인자)')
    string(name: 'NEXT_PUBLIC_ADSENSE_CLIENT', defaultValue: 'ca-pub-6890085609044109', description: '애드센스 클라이언트 ID (빌드 인자)')
  }

  environment { TZ = 'Asia/Seoul' }

  stages {
    stage('Checkout') {
      steps {
        script {
          if (params.CREDENTIALS?.trim()) {
            checkout([$class: 'GitSCM',
              branches: [[name: "*/${params.BRANCH}"]],
              userRemoteConfigs: [[url: params.REPO_URL, credentialsId: params.CREDENTIALS]]
            ])
          } else {
            checkout([$class: 'GitSCM',
              branches: [[name: "*/${params.BRANCH}"]],
              userRemoteConfigs: [[url: params.REPO_URL]]
            ])
          }
        }
      }
    }

    stage('Docker Build & Tag') {
      steps {
        sh """
          GIT_SHA=\$(git rev-parse --short HEAD)
          docker build --no-cache -f ${params.DOCKERFILE} \
            --build-arg NEXT_PUBLIC_KAKAO_JS_KEY=${params.NEXT_PUBLIC_KAKAO_JS_KEY} \
            --build-arg NEXT_PUBLIC_ADSENSE_CLIENT=${params.NEXT_PUBLIC_ADSENSE_CLIENT} \
            -t ${params.IMAGE_NAME}:\$GIT_SHA \
            -t ${params.IMAGE_NAME}:latest \
            ${params.BUILD_CTX}
          docker images | grep ^${params.IMAGE_NAME}\\s | head -n 5 || true
        """
      }
    }

    stage('Deploy (Compose up)') {
      steps {
        sh """
          docker compose -f ${params.COMPOSE_FILE} up -d --build --force-recreate ${params.SERVICE_NAME}
          docker ps --format 'table {{.Names}}\\t{{.Image}}\\t{{.Status}}' | (head -n 1; grep ${params.CONTAINER_NAME} || true)
        """
      }
    }

    stage('Cleanup dangling images') {
      steps { sh 'docker image prune -f || true' }
    }
  }

  post {
    success { echo "✅ 배포 성공: ${params.SERVICE_NAME}" }
    failure { echo "❌ 배포 실패" }
  }
}
